import { useState } from "react";
import { base44 } from "@/api/base44Client";
import { Cpu, Loader2 } from "lucide-react";
import ReactMarkdown from "react-markdown";

export default function AiEngineeringAssistant({ project, onResult }) {
  const [running, setRunning] = useState(false);
  const [error, setError] = useState("");
  const recommendation = project.ai_engineering_recommendation;

  const run = async () => {
    setRunning(true);
    setError("");
    try {
      const summary = (project.items || []).map((it, i) => ({
        n: i + 1,
        type: it.foundation_type,
        quantity: it.quantity,
        length_in: it.length_inches,
        width_in: it.width_inches,
        diameter_in: it.diameter,
        depth_in: it.depth_inches,
        rebar: it.include_rebar ? it.rebar_size : "none",
      }));
      const poles = (project.poles || []).map((p) => ({
        height_in: p.height_inches,
        signs: (p.signs || []).length,
      }));

      const res = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a structural engineer sizing sign foundations and poles.
Foundations: ${JSON.stringify(summary)}
Poles: ${JSON.stringify(poles)}
Concrete mix: ${project.project_concrete_type || "unspecified"}

Give concise wind-load and sizing recommendations: assumed wind speed and exposure, overturning/embedment check per each foundation, whether the footing/pillar size and depth are adequate, recommended rebar, and any red flags. Use short markdown sections and keep it under 250 words.`,
        response_json_schema: {
          type: "object",
          properties: {
            recommendation_markdown: { type: "string" },
            adequate: { type: "boolean" },
            assumed_wind_speed_mph: { type: "number" },
          },
        },
      });

      onResult({
        ai_engineering_recommendation: res.recommendation_markdown || "",
        ai_engineering_data: {
          adequate: res.adequate,
          assumed_wind_speed_mph: res.assumed_wind_speed_mph,
          generated_at: new Date().toISOString(),
        },
      });
    } catch (e) {
      setError(e.message || "The engineering calculator could not run.");
    } finally {
      setRunning(false);
    }
  };

  return (
    <div className="bg-violet-50 border border-violet-200 rounded-sm p-3 mb-3">
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-start gap-2">
          <Cpu className="w-4 h-4 text-violet-600 mt-0.5" aria-hidden="true" />
          <div>
            <h3 className="text-[13px] font-bold text-violet-900">AI Engineering Assistant</h3>
            <p className="text-[11px] text-violet-700">
              Generate concise wind load calculations and sizing recommendations for your foundation
              and poles.
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={run}
          disabled={running}
          className="h-[30px] px-3 flex items-center gap-1.5 rounded-sm bg-violet-600 text-white text-[12px] font-semibold hover:bg-violet-700 disabled:opacity-60 flex-shrink-0"
        >
          {running ? <Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" /> : <Cpu className="w-3.5 h-3.5" aria-hidden="true" />}
          {running ? "Calculating…" : "Run AI Engineering Calculator"}
        </button>
      </div>

      {error && <div role="alert" className="mt-2 text-[11px] text-red-600">{error}</div>}

      {recommendation && (
        <div className="mt-3 bg-white border border-violet-200 rounded-sm p-3 text-[12px] text-gray-700 prose prose-sm max-w-none">
          <ReactMarkdown>{recommendation}</ReactMarkdown>
        </div>
      )}
    </div>
  );
}

// Artwork upload — Feature #19.
// Hybrid pipeline: free metadata first (SVG viewBox / PDF MediaBox / image px+DPI),
// AI vision (InvokeLLM) as fallback.

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { UploadCloud, FileImage, Wand2, Loader2 } from "lucide-react";
import { base44 } from "@/api/base44Client";

const svgDims = async (file) => {
  const text = await file.text();
  const m = text.match(/viewBox\s*=\s*"([\d.\s-]+)"/i);
  if (m) {
    const parts = m[1].split(/\s+/).map(parseFloat);
    if (parts.length >= 4) return { w: parts[2], h: parts[3], unit: "svg" };
  }
  const wm = text.match(/<svg[^>]*\bwidth\s*=\s*"([\d.]+)/i);
  const hm = text.match(/<svg[^>]*\bheight\s*=\s*"([\d.]+)/i);
  if (wm && hm) return { w: parseFloat(wm[1]), h: parseFloat(hm[1]), unit: "svg" };
  return null;
};

const imgDims = (file) => new Promise((resolve) => {
  const url = URL.createObjectURL(file);
  const img = new Image();
  img.onload = () => { URL.revokeObjectURL(url); resolve({ w: img.naturalWidth, h: img.naturalHeight, unit: "px" }); };
  img.onerror = () => { URL.revokeObjectURL(url); resolve(null); };
  img.src = url;
});

const pdfDims = async (file) => {
  const buf = await file.arrayBuffer();
  const sample = new TextDecoder("latin1").decode(buf.slice(0, 200_000));
  const m = sample.match(/\/MediaBox\s*\[\s*([\d.\-]+)\s+([\d.\-]+)\s+([\d.\-]+)\s+([\d.\-]+)\s*\]/);
  if (!m) return null;
  const x = parseFloat(m[1]); const y = parseFloat(m[2]);
  const x2 = parseFloat(m[3]); const y2 = parseFloat(m[4]);
  const wPt = Math.abs(x2 - x); const hPt = Math.abs(y2 - y);
  return { w: wPt / 72, h: hPt / 72, unit: "in" };
};

const aiDims = async (file) => {
  const { file_url } = await base44.integrations.Core.UploadFile({ file });
  const response = await base44.integrations.Core.InvokeLLM({
    prompt:
      "Look at this artwork file. Return the width and height of the printable artwork " +
      "bounding box in INCHES. If the file shows real-world dimensions or has a known " +
      "common size, use that. Otherwise estimate from proportions. Always positive numbers.",
    file_urls: [file_url],
    response_json_schema: {
      type: "object",
      properties: {
        width_inches:  { type: "number" },
        height_inches: { type: "number" },
        confidence:    { type: "string", enum: ["low", "medium", "high"] },
        reasoning:     { type: "string" },
      },
      required: ["width_inches", "height_inches"],
    },
  });
  if (!response?.width_inches || !response?.height_inches) return null;
  return {
    w: parseFloat(response.width_inches),
    h: parseFloat(response.height_inches),
    unit: "in",
    confidence: response.confidence,
    reasoning: response.reasoning,
  };
};

export default function VinylArtworkUploadDialog({ open, onClose, onAdd }) {
  const [file, setFile] = useState(null);
  const [parsed, setParsed] = useState(null);
  const [scale, setScale] = useState(96);
  const [error, setError] = useState(null);
  const [aiLoading, setAiLoading] = useState(false);

  const reset = () => { setFile(null); setParsed(null); setError(null); setAiLoading(false); };

  const handleFile = async (f) => {
    setError(null); setParsed(null); setFile(f);
    if (!f) return;
    try {
      let dims = null;
      const name = f.name.toLowerCase();
      if (f.type === "image/svg+xml" || name.endsWith(".svg")) {
        dims = await svgDims(f); if (dims) dims.source = "svg-viewBox";
      } else if (f.type === "application/pdf" || name.endsWith(".pdf")) {
        dims = await pdfDims(f); if (dims) dims.source = "pdf-MediaBox";
      } else if (name.endsWith(".ai")) {
        dims = await pdfDims(f); if (dims) dims.source = "ai-MediaBox";
      } else if (f.type.startsWith("image/")) {
        dims = await imgDims(f); if (dims) dims.source = "raster-pixels";
      }
      if (dims) setParsed({ name: f.name.replace(/\.[^.]+$/, ""), ...dims });
      else setError("Couldn't read dimensions from this file. Try AI fallback below.");
    } catch (e) { setError(e.message || "Failed to parse file."); }
  };

  const runAi = async () => {
    if (!file) return;
    setAiLoading(true); setError(null);
    try {
      const dims = await aiDims(file);
      if (!dims) { setError("AI couldn't determine dimensions."); return; }
      setParsed({ name: file.name.replace(/\.[^.]+$/, ""), ...dims, source: `ai-${dims.confidence || ""}` });
    } catch (e) { setError("AI lookup failed: " + (e.message || e)); }
    setAiLoading(false);
  };

  const finalInches = (() => {
    if (!parsed) return { w: 0, h: 0 };
    if (parsed.unit === "in" || parsed.unit === "svg") return { w: parsed.w, h: parsed.h };
    if (parsed.unit === "px") return { w: parsed.w / Math.max(1, scale), h: parsed.h / Math.max(1, scale) };
    return { w: parsed.w, h: parsed.h };
  })();

  const handleAdd = () => {
    if (!parsed) return;
    onAdd({
      id: `it-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      description: parsed.name,
      width_inches: parseFloat(finalInches.w.toFixed(3)),
      height_inches: parseFloat(finalInches.h.toFixed(3)),
      quantity: 1,
      bleed_inches: 0,
      allow_rotation: true,
    });
    reset(); onClose();
  };

  const sourceLabel = ({
    "svg-viewBox":    "✓ SVG viewBox (exact)",
    "pdf-MediaBox":   "✓ PDF MediaBox (exact)",
    "ai-MediaBox":    "✓ AI artwork MediaBox (exact)",
    "raster-pixels":  "Raster pixels — set DPI",
  })[parsed?.source] || (parsed?.source?.startsWith("ai-") ? `🤖 AI vision (${parsed.confidence || "estimated"})` : null);

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) { reset(); onClose(); } }}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <UploadCloud className="w-5 h-5 text-blue-600" /> Upload Artwork
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          <p className="text-xs text-slate-600">
            Drop an SVG, PDF, AI, or image. Dimensions are read from the file (free).
            If the file has none, use the AI button to detect them.
          </p>
          <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center bg-slate-50">
            <input
              type="file"
              accept=".svg,.pdf,.ai,image/svg+xml,image/png,image/jpeg,image/webp,application/pdf"
              onChange={(e) => handleFile(e.target.files?.[0])}
              className="text-xs"
            />
            <FileImage className="w-8 h-8 mx-auto mt-2 text-slate-400" />
          </div>

          {parsed?.unit === "px" && (
            <div>
              <Label className="text-xs">DPI (pixels per inch)</Label>
              <Input type="number" value={scale}
                onChange={(e) => setScale(parseFloat(e.target.value) || 96)}
                className="h-8 text-sm tabular-nums" />
            </div>
          )}

          {parsed && (
            <div className="bg-emerald-50 border border-emerald-200 rounded p-3 text-xs space-y-1">
              <div className="font-semibold">{parsed.name}</div>
              {sourceLabel && <div className="text-[11px] text-slate-600">{sourceLabel}</div>}
              <div className="text-slate-700">
                Raw: {parsed.w.toFixed(2)} × {parsed.h.toFixed(2)} {parsed.unit}
              </div>
              <div className="font-medium tabular-nums text-emerald-900">
                → {finalInches.w.toFixed(2)}″ × {finalInches.h.toFixed(2)}″
              </div>
              {parsed.reasoning && (
                <div className="text-[10px] text-slate-500 italic mt-1">{parsed.reasoning}</div>
              )}
            </div>
          )}

          {file && (
            <Button variant="outline" size="sm" onClick={runAi} disabled={aiLoading} className="w-full">
              {aiLoading
                ? <><Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" /> Asking AI…</>
                : <><Wand2 className="w-3.5 h-3.5 mr-1" /> {parsed ? "Re-check with AI" : "Use AI to detect dimensions"}</>}
            </Button>
          )}

          {error && <div className="p-2 bg-red-50 border border-red-200 rounded text-xs text-red-700">{error}</div>}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => { reset(); onClose(); }}>Cancel</Button>
          <Button onClick={handleAdd} disabled={!parsed} className="bg-blue-600 hover:bg-blue-700 text-white">
            Add as Part
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Sparkles, Loader2, Wand2 } from "lucide-react";
import { base44 } from "@/api/base44Client";

const SCHEMA = {
  type: "object",
  properties: {
    letter_purchases: {
      type: "array",
      items: {
        type: "object",
        properties: {
          letter_type: {
            type: "string",
            enum: ["raceway", "channel_raceway_mounted", "channel_flush_mounted", "channel_halo_lit", "capsule_logo_pillbox", "dimensional_letters"]
          },
          description: { type: "string" },
          qty: { type: "number" },
          size_value: { type: "number", description: "Vertical inches for channel letters, linear feet for raceway, sq ft for capsule/dimensional" },
          install_height_feet: { type: "number" },
          wall_material: { type: "string", enum: ["eifs", "stucco", "brick", "concrete", "metal", "wood", "glass", "drywall"] }
        },
        required: ["letter_type", "qty"]
      }
    },
    notes: { type: "string", description: "Brief summary of what was inferred and any assumptions made" }
  }
};

export default function AIScopeWriterModal({ open, onClose, onApply }) {
  const [rawText, setRawText] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [mode, setMode] = useState("append"); // "append" | "replace"

  const generate = async () => {
    if (!rawText.trim()) return;
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const res = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a sign-shop estimator. Parse the following rough client request into structured channel letter purchase line items.

Map letter types as follows:
- "flush mount" or "face-lit" → channel_flush_mounted
- "halo lit" or "backlit" or "reverse channel" → channel_halo_lit
- "raceway mounted" → channel_raceway_mounted
- just "raceway" (no letters) → raceway
- "dimensional" or "flat cut" or "pvc letters" → dimensional_letters
- "logo" or "capsule" or "pillbox" → capsule_logo_pillbox

For size_value: use vertical inches for channel letters (e.g. "24 inch letters" → 24), linear feet for raceway, square feet for capsule/dimensional.
Default install_height_feet to 12 if not mentioned. Default wall_material to "eifs" if not mentioned.

CLIENT REQUEST:
${rawText}`,
        response_json_schema: SCHEMA
      });
      setResult(res);
    } catch (e) {
      setError(e.message || "Generation failed");
    }
    setLoading(false);
  };

  const apply = () => {
    if (!result?.letter_purchases?.length) return;
    if (mode === "replace" && !confirm("Replace all existing letter rows with the AI-generated items?")) return;
    onApply(result.letter_purchases, mode);
    setRawText("");
    setResult(null);
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-purple-600" />
            AI Scope Writer
          </DialogTitle>
          <p className="text-xs text-slate-500">Paste rough client notes — AI will extract structured letter line items.</p>
        </DialogHeader>

        <div className="space-y-3">
          <Textarea
            value={rawText}
            onChange={(e) => setRawText(e.target.value)}
            placeholder={`Example:\n"Customer wants 12 halo-lit channel letters, 18 inches tall, mounted to a brick wall about 15 feet up. Also need a 10ft raceway."`}
            className="h-32 text-sm"
            disabled={loading}
          />

          {error && (
            <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2">{error}</div>
          )}

          {result?.letter_purchases?.length > 0 && (
            <div className="border border-purple-200 bg-purple-50/40 rounded-lg p-3 space-y-2">
              <div className="text-xs font-semibold text-purple-900 flex items-center gap-1">
                <Wand2 className="w-3.5 h-3.5" />
                AI generated {result.letter_purchases.length} line item{result.letter_purchases.length !== 1 ? "s" : ""}:
              </div>
              <div className="space-y-1.5">
                {result.letter_purchases.map((p, i) => (
                  <div key={i} className="bg-white rounded border border-purple-100 px-2 py-1.5 text-xs flex items-center gap-2 flex-wrap">
                    <Badge variant="outline" className="bg-purple-100 text-purple-800 border-purple-200 text-[10px]">
                      {p.letter_type?.replace(/_/g, " ")}
                    </Badge>
                    <span className="font-semibold">{p.qty}×</span>
                    {p.size_value > 0 && <span className="text-slate-600">{p.size_value}"</span>}
                    {p.description && <span className="text-slate-600 italic">{p.description}</span>}
                    {p.install_height_feet > 0 && <span className="text-slate-500">@ {p.install_height_feet}ft</span>}
                    {p.wall_material && <span className="text-slate-500">on {p.wall_material}</span>}
                  </div>
                ))}
              </div>
              {result.notes && (
                <div className="text-[11px] text-slate-600 italic border-t border-purple-200 pt-1.5">
                  <strong>AI notes:</strong> {result.notes}
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter className="gap-2 sm:justify-between flex-wrap">
          {result ? (
            <div className="inline-flex rounded-lg border border-slate-200 bg-slate-50 p-0.5 text-xs">
              <button
                type="button"
                onClick={() => setMode("append")}
                className={`px-2.5 py-1 rounded-md font-medium transition-colors ${mode === "append" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
              >
                Append
              </button>
              <button
                type="button"
                onClick={() => setMode("replace")}
                className={`px-2.5 py-1 rounded-md font-medium transition-colors ${mode === "replace" ? "bg-white text-red-700 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
              >
                Clear & Replace
              </button>
            </div>
          ) : <div />}
          <div className="flex gap-2">
            <Button variant="outline" onClick={onClose} disabled={loading}>Cancel</Button>
            {!result ? (
              <Button onClick={generate} disabled={loading || !rawText.trim()} className="bg-purple-600 hover:bg-purple-700 text-white">
                {loading ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Generating...</> : <><Sparkles className="w-4 h-4 mr-2" /> Generate Line Items</>}
              </Button>
            ) : (
              <Button onClick={apply} className={mode === "replace" ? "bg-red-600 hover:bg-red-700 text-white" : "bg-green-600 hover:bg-green-700 text-white"}>
                <Wand2 className="w-4 h-4 mr-2" /> {mode === "replace" ? "Replace All Letters" : "Add to Estimate"}
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Sparkles, Loader2, Wand2, Image as ImageIcon, X, Upload } from "lucide-react";
import { base44 } from "@/api/base44Client";

const SCHEMA = {
  type: "object",
  properties: {
    items: {
      type: "array",
      items: {
        type: "object",
        properties: {
          description: { type: "string" },
          installation_type: {
            type: "string",
            enum: ["flush_mount", "halo_lit", "raceway", "dimensional_lettering"]
          },
          qty_letters: { type: "number" },
          letter_size: {
            type: "string",
            enum: ["extra_small", "small", "medium", "large", "extra_large", "extra_extra_large"]
          },
          letter_height_inches: { type: "number" },
          installation_height_feet: { type: "number" },
          raceway_length_feet: { type: "number" },
          wall_material: { type: "string", enum: ["eifs", "stucco", "brick", "concrete", "metal", "wood", "glass", "drywall"] },
          parapet: { type: "boolean" },
          poor_electrical_access: { type: "boolean" },
          thick_hollow_walls: { type: "boolean" },
          escort_required: { type: "boolean" },
          badging_checkin: { type: "boolean" },
          after_hours_weekend: { type: "boolean" },
          set_hours_installation: { type: "boolean" },
          poor_site_access: { type: "boolean" }
        },
        required: ["installation_type", "qty_letters"]
      }
    },
    notes: { type: "string" }
  }
};

export default function AIInstallScopeModal({ open, onClose, onApply }) {
  const [rawText, setRawText] = useState("");
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [mockups, setMockups] = useState([]); // [{ url, name }]
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [mode, setMode] = useState("append"); // "append" | "replace"

  const handleFiles = async (files) => {
    if (!files || files.length === 0) return;
    setUploading(true);
    setError(null);
    try {
      const uploaded = [];
      for (const file of Array.from(files)) {
        const { file_url } = await base44.integrations.Core.UploadFile({ file });
        uploaded.push({ url: file_url, name: file.name });
      }
      setMockups((prev) => [...prev, ...uploaded]);
    } catch (e) {
      setError(e.message || "Upload failed");
    }
    setUploading(false);
  };

  const removeMockup = (idx) => {
    setMockups((prev) => prev.filter((_, i) => i !== idx));
  };

  const canGenerate = !loading && !uploading && (rawText.trim().length > 0 || mockups.length > 0);

  const generate = async () => {
    if (!canGenerate) return;
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const hasImages = mockups.length > 0;
      const hasText = rawText.trim().length > 0;

      const imageInstructions = hasImages ? `
You've also been provided with ${mockups.length === 1 ? "a sign mockup image" : `${mockups.length} sign mockup images`}. Carefully analyze:
- Count the actual letters/characters in each mockup (don't include spaces in count)
- Estimate letter height proportions if a height isn't stated
- Identify if the sign appears to be flush-mounted, halo-lit (backlit glow), raceway-mounted (visible horizontal mounting bar behind letters), or dimensional (flat cut, non-illuminated)
- Note wall material if visible (EIFS, brick, stucco, glass, metal, etc.)
- Flag any visible site conditions (parapet wall, height obstacles, signs of difficult access)
- If multiple distinct signs appear, create a separate line item for each
${hasText ? "Use the written notes below as the primary source of truth; the image fills in gaps." : "Generate items based on what you observe in the image(s)."}` : "";

      const res = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a sign-installation estimator. Parse the input into structured installation line items.
